// Parse SDR JSON output and prepare for Node.js service
const rawOutput = $input.first().json.output || $input.first().json.text;

let sdrData;
try {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  sdrData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(rawOutput);
} catch (error) {
  throw new Error('Failed to parse SDR output');
}

if (!sdrData.evars || !sdrData.props || !sdrData.events) {
  throw new Error('SDR missing required fields');
}

// Get original file data
const originalBinary = $('Create Binary').first().binary.file;
const clientName = $('Parse Requirements').first().json.clientName;

return [{
  json: {
    success: true,
    clientName: clientName,
    originalFileBase64: originalBinary.data,
    sdr: sdrData,
    stats: {
      evars: sdrData.evars.length,
      props: sdrData.props.length,
      events: sdrData.events.length
    }
  }
}];

// Parse TSD Agent output (2-3 files: JavaScript, Markdown, optional Launch Payload)
const input = $input.first().json;

// TSD Agent may return: { clientName, output: {...} } OR { output: { clientName, ... } }
const tsdOutput = input.output || input;

// Fallback logic for clientName extraction
const clientName = input.clientName || input.output?.clientName || tsdOutput.clientName;

if (!clientName) {
  throw new Error('TSD output missing clientName field in all possible locations (input.clientName, input.output.clientName, tsdOutput.clientName)');
}

if (!tsdOutput.javascript || !tsdOutput.markdown) {
  throw new Error('TSD output missing required fields: javascript and/or markdown');
}

// Check for optional launchPayload
const hasLaunchPayload = !!tsdOutput.launchPayload;
if (!hasLaunchPayload) {
  console.warn('⚠️  WARNING: launchPayload not found in TSD output - operating in 2-file mode (JavaScript + Markdown only)');
}

// Generate filenames with timestamp
const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
const jsFilename = `${clientName}_adobeDataLayer_${timestamp}.js`;
const mdFilename = `${clientName}_TSD_${timestamp}.md`;
const launchFilename = `${clientName}_LaunchPayload_${timestamp}.json`;

// Stringify Launch Payload JSON
const launchPayloadStr = typeof tsdOutput.launchPayload === 'string' 
  ? tsdOutput.launchPayload 
  : JSON.stringify(tsdOutput.launchPayload, null, 2);

console.log(`=== Parse TSD Output (${hasLaunchPayload ? '3' : '2'} Files) ===`);
console.log('Client:', clientName);
console.log('JavaScript size:', tsdOutput.javascript.length);
console.log('Markdown size:', tsdOutput.markdown.length);
if (hasLaunchPayload) {
  console.log('Launch Payload size:', launchPayloadStr.length);
}

return [{
  json: {
    clientName: clientName,
    files: {
      javascript: {
        filename: jsFilename,
        content: tsdOutput.javascript,
        size: tsdOutput.javascript.length,
        type: 'application/javascript'
      },
      markdown: {
        filename: mdFilename,
        content: tsdOutput.markdown,
        size: tsdOutput.markdown.length,
        type: 'text/markdown'
      },
      ...(hasLaunchPayload && {
        launchPayload: {
          filename: launchFilename,
          content: launchPayloadStr,
          size: launchPayloadStr.length,
          type: 'application/json'
        }
      })
    },
    stats: {
      jsLines: tsdOutput.javascript.split('\n').length,
      mdLines: tsdOutput.markdown.split('\n').length,
      ...(hasLaunchPayload && {
        launchRulesCount: (tsdOutput.launchPayload.rules || []).length
      }),
      generatedAt: new Date().toISOString()
    }
  }
}];

// Convert files to binary format for Google Drive with UTF-8 encoding (2-3 files)
const parsedData = $('Parse TSD Output').first().json;
const folderId = $input.first().json.id;

// Convert text to base64 with UTF-8 encoding for JavaScript file
const jsContent = parsedData.files.javascript.content;
const jsBase64 = Buffer.from(jsContent, 'utf-8').toString('base64');

// Convert text to base64 with UTF-8 encoding for Markdown file
const mdContent = parsedData.files.markdown.content;
const mdBase64 = Buffer.from(mdContent, 'utf-8').toString('base64');

const result = [
  {
    json: {
      clientName: parsedData.clientName,
      filename: parsedData.files.javascript.filename,
      fileType: 'JavaScript',
      folderId: folderId,
      stats: parsedData.stats
    },
    binary: {
      data: {
        data: jsBase64,
        mimeType: 'text/plain; charset=utf-8',
        fileName: parsedData.files.javascript.filename
      }
    }
  },
  {
    json: {
      clientName: parsedData.clientName,
      filename: parsedData.files.markdown.filename,
      fileType: 'Markdown',
      folderId: folderId,
      stats: parsedData.stats
    },
    binary: {
      data: {
        data: mdBase64,
        mimeType: 'text/plain; charset=utf-8',
        fileName: parsedData.files.markdown.filename
      }
    }
  }
];

// Add Launch Payload if exists
if (parsedData.files.launchPayload) {
  const launchContent = parsedData.files.launchPayload.content;
  const launchBase64 = Buffer.from(launchContent, 'utf-8').toString('base64');

  result.push({
    json: {
      clientName: parsedData.clientName,
      filename: parsedData.files.launchPayload.filename,
      fileType: 'Launch Payload',
      folderId: folderId,
      stats: parsedData.stats
    },
    binary: {
      data: {
        data: launchBase64,
        mimeType: 'application/json; charset=utf-8',
        fileName: parsedData.files.launchPayload.filename
      }
    }
  });
} else {
  console.warn('⚠️  WARNING: launchPayload not found in parsed data - uploading 2 files only');
}

return result;

// Collect all uploaded files info (2-3 files: JavaScript, Markdown, optional Launch Payload)
const items = $input.all();
const clientName = items[0].json.name.split('_')[0];

console.log('=== TSD Files Uploaded to Google Drive ===');
console.log('Client:', clientName);
console.log('Total files uploaded:', items.length);

const uploadedFiles = items.map(item => ({
  fileId: item.json.id,
  fileName: item.json.name,
  mimeType: item.json.mimeType,
  webViewLink: item.json.webViewLink,
  webContentLink: item.json.webContentLink,
  createdTime: item.json.createdTime
}));

// Categorize files by type
const fileTypes = {
  javascript: uploadedFiles.find(f => f.fileName.includes('adobeDataLayer')),
  markdown: uploadedFiles.find(f => f.fileName.includes('TSD') && f.fileName.endsWith('.md')),
  launchPayload: uploadedFiles.find(f => f.fileName.includes('LaunchPayload'))
};

const hasLaunchPayload = !!fileTypes.launchPayload;
const fileTypesList = hasLaunchPayload 
  ? 'JavaScript, Markdown, Launch Payload'
  : 'JavaScript, Markdown';

uploadedFiles.forEach(file => {
  console.log(`- ${file.fileName}`);
  console.log(`  ID: ${file.fileId}`);
  console.log(`  Link: ${file.webViewLink}`);
});

if (!hasLaunchPayload) {
  console.warn('⚠️  WARNING: Launch Payload file not found - TSD Agent did not generate launchPayload output');
}

return [{
  json: {
    success: true,
    clientName: clientName,
    googleDrive: {
      folder: `TSD/${clientName}`,
      files: uploadedFiles,
      fileTypes: fileTypes
    },
    totalFiles: items.length,
    message: `Successfully uploaded ${items.length} files (${fileTypesList}) to Google Drive${!hasLaunchPayload ? ' - launchPayload not generated' : ''}`
  }
}];
